using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEngine.UIElements;using UnityEditor;using EchoSphere.Core;using EchoSphere.Presentation;
public static class HudCurrencyCheck {
 public static object Main(){
  if(!Application.isPlaying)throw new Exception("Play required");string output=Path.GetFullPath("Library/hud-currency");Directory.CreateDirectory(output);
  var owner=new GameObject("HUD currency check");var panel=ScriptableObject.CreateInstance<PanelSettings>();panel.scaleMode=PanelScaleMode.ConstantPixelSize;panel.scale=1;panel.forceGammaRendering=true;panel.themeStyleSheet=Resources.Load<ThemeStyleSheet>("EchoSphere/SourceUiTheme");
  RenderTexture target=null;var doc=owner.AddComponent<UIDocument>();doc.panelSettings=panel;var root=doc.rootVisualElement;root.style.position=Position.Absolute;root.style.left=root.style.right=root.style.top=root.style.bottom=0;NativeHudView view=null;
  int phase=0,settled=0,last=-1,checks=0,actions=0;bool background=Application.runInBackground;Application.runInBackground=true;EditorApplication.isPaused=false;EditorApplication.ExecuteMenuItem("Window/General/Game");double started=EditorApplication.timeSinceStartup;
  int[] widths={320,393,540,960,320,393},heights={700,873,960,540,568,873};int?[] amounts={0,12345,999999,int.MaxValue,int.MaxValue,null};
  void Assert(bool value,string why){checks++;if(!value)throw new Exception(why);}
  void Setup(){view?.Dispose();if(target!=null){panel.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);}target=new RenderTexture(widths[phase],heights[phase],24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);target.Create();panel.targetTexture=target;view=new NativeHudView(root,()=>{actions++;return false;},_=>null);view.Bind(new NativeHudView.State{Russian=phase<2||phase>=4,RunCurrency=amounts[phase],Level="12",Hp="100/100",Resonance="25/100",Spheres="3/5",Wave="5",Links="2",Timer="03:29",HasRegion=true,Region=phase<2?"РАСКОЛОТЫЙ БАСТИОН":"FRACTURED BASTION",Phase="1",Pocket="2"});view.SetInterfaceScale(phase==3?1.25f:phase==4?.75f:1);settled=0;}
  Setup();EditorApplication.CallbackFunction tick=null;
  void Finish(string status){EditorApplication.update-=tick;view?.Dispose();panel.targetTexture=null;UnityEngine.Object.Destroy(owner);target.Release();UnityEngine.Object.Destroy(target);UnityEngine.Object.Destroy(panel);Application.runInBackground=background;File.WriteAllText(Path.Combine(output,"result.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{result=status,viewports=phase,checks,actions}));}
  tick=()=>{try{if(!Application.isPlaying||EditorApplication.timeSinceStartup-started>90){Finish("FAIL deadline");return;}if(last==Time.frameCount)return;last=Time.frameCount;view.Prepare(1);if(++settled<12||!view.Ready)return;
   var label=root.Q<Label>("hud-run-currency");var right=root.Q("hud-right");var radar=root.Q("native-hud-radar");var left=root.Q("hud-left");Assert(Math.Abs(left.worldBound.width-widths[phase]/2f)<1&&Math.Abs(right.worldBound.width-widths[phase]/2f)<1,"Top panels must each occupy half the viewport independently of UI scale");Assert(label!=null&&label.parent.name=="hud-run-currency-row"&&right.Contains(label)&&root.Q("hud-radar-row").Contains(label),"Counter not in upper-right HUD");
   if(amounts[phase].HasValue){Assert(label.text.EndsWith(amounts[phase].Value.ToString(System.Globalization.CultureInfo.InvariantCulture)),"Incorrect balance");Assert(label.worldBound.xMin>=right.worldBound.xMin&&label.worldBound.yMin>=right.worldBound.yMin&&label.worldBound.xMax<=radar.worldBound.xMin&&label.worldBound.yMax<=right.worldBound.yMax,"Currency overlaps/outside HUD");Assert(label.resolvedStyle.fontSize==8,"Counter not compact text");view.SetRunCurrency(7,phase<2||phase>=4);Assert(label.text.EndsWith("7"),"Balance does not update independently of full HUD bind");view.SetRunCurrency(amounts[phase],phase<2||phase>=4);}else Assert(label.style.display.value==DisplayStyle.None,"Hidden wallet remains visible");
   if(phase==1){var old=RenderTexture.active;var shot=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);try{RenderTexture.active=target;shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(output,"portrait.png"),shot.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.Destroy(shot);}}
   if(phase==5){view.SetMerchantStatus("00:12",false);var indicator=root.Q("hud-merchant");Assert(right.Contains(indicator)&&indicator.style.display.value==DisplayStyle.Flex,"Merchant timer belongs to upper HUD");Assert(root.Q("merchant-open-button")==null,"No bottom merchant button");view.SetMerchantStatus(null,false);Assert(indicator.style.display.value==DisplayStyle.None,"Merchant timer hides without rebuilding HUD");Assert(actions==0,"UI check invoked gameplay");}
   if(++phase==6)Finish("PASS");else Setup();
  }catch(Exception e){Finish("FAIL "+e);}};EditorApplication.update+=tick;return "Scheduled six viewport HUD currency check";
 }
}
